export function injectFault(value,fault){switch(fault?.type){case'TIMEOUT':{const e=new Error('injected timeout');e.code='TIMEOUT';throw e;}case'SCHEMA_DRIFT':return {...value,__schemaDrift:true,[fault.removeField??'requiredField']:undefined};case'STALE':return {...value,observedAt:fault.observedAt??'2000-01-01T00:00:00Z'};case'MISSING':return null;case'PARTIAL':return {...value,quality:'DEGRADED'};default:return structuredClone(value);}}
